local GlassKilnSealMaker = {}
local PRODUCTS = {
    iron_glasskilnseal = { name = "Železni tesnilo za steklarske peči", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni tesnilo za steklarske peči za steklarje." },
    bronze_glasskilnseal = { name = "Bronast tesnilo za steklarske peči", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast tesnilo za steklarske peči za steklarje." },
    silver_glasskilnseal = { name = "Srebrn tesnilo za steklarske peči", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn tesnilo za steklarske peči za steklarje." },
    gilded_glasskilnseal = { name = "Pozlačen tesnilo za steklarske peči", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen tesnilo za steklarske peči za steklarje." },
    jewel_set_glasskilnseal = { name = "Draguljast tesnilo za steklarske peči", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast tesnilo za steklarske peči za steklarje." },
    royal_sovereign_glasskilnseal = { name = "Kraljevski suveren tesnilo za steklarske peči", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren tesnilo za steklarske peči z biseri za krono." },
}
local BUILDINGS = {
    glasskilnseal_workshop = { name = "Glasskilnseal delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    glasskilnseal_house = { name = "Glasskilnseal hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_glasskilnseal_atelier = { name = "Mojstrski glasskilnseal atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_glasskilnseal_palace = { name = "Suverena glasskilnseal palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
GlassKilnSealMaker.ironStock=12; GlassKilnSealMaker.bronzeStock=10; GlassKilnSealMaker.woodStock=14; GlassKilnSealMaker.leatherStock=12; GlassKilnSealMaker.silverStock=8; GlassKilnSealMaker.goldStock=6; GlassKilnSealMaker.jewelStock=4; GlassKilnSealMaker.pearlStock=4
GlassKilnSealMaker.productStock = {}; GlassKilnSealMaker.buildings = {}; GlassKilnSealMaker.maker = nil; GlassKilnSealMaker.activeMaking = {}; GlassKilnSealMaker.totalProducts = 0; GlassKilnSealMaker.dayTimer = 0
function GlassKilnSealMaker.init() GlassKilnSealMaker.ironStock=12; GlassKilnSealMaker.bronzeStock=10; GlassKilnSealMaker.woodStock=14; GlassKilnSealMaker.leatherStock=12; GlassKilnSealMaker.silverStock=8; GlassKilnSealMaker.goldStock=6; GlassKilnSealMaker.jewelStock=4; GlassKilnSealMaker.pearlStock=4; GlassKilnSealMaker.productStock={}; GlassKilnSealMaker.buildings={}; GlassKilnSealMaker.maker=nil; GlassKilnSealMaker.activeMaking={}; GlassKilnSealMaker.totalProducts=0; GlassKilnSealMaker.dayTimer=0; print("[GlassKilnSealMaker] Royal Glass Kiln Seal Maker System initialized (6 products, 4 buildings)") end
function GlassKilnSealMaker.hireMaker(n,s) s=s or math.random(55,90); local c=570+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GlassKilnSealMaker.maker={name=n or ("Tesnilkar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Tesnilkar najet: %s (spretnost: %d)",GlassKilnSealMaker.maker.name,s),"success") end; return true end
function GlassKilnSealMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GlassKilnSealMaker.build(id) local ok,e=GlassKilnSealMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GlassKilnSealMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GlassKilnSealMaker.getQualityBonus() local b=0; for _,bd in ipairs(GlassKilnSealMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GlassKilnSealMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GlassKilnSealMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GlassKilnSealMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GlassKilnSealMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GlassKilnSealMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GlassKilnSealMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GlassKilnSealMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GlassKilnSealMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GlassKilnSealMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GlassKilnSealMaker.buildings==0 then return false,"Potrebna tesnilna delavnica" end; if not GlassKilnSealMaker.maker then return false,"Potreben tesnilkar" end; return true end
function GlassKilnSealMaker.make(pt,qty) qty=qty or 1; local ok,e=GlassKilnSealMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GlassKilnSealMaker.ironStock=GlassKilnSealMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GlassKilnSealMaker.bronzeStock=GlassKilnSealMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GlassKilnSealMaker.woodStock=GlassKilnSealMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GlassKilnSealMaker.leatherStock=GlassKilnSealMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GlassKilnSealMaker.silverStock=GlassKilnSealMaker.silverStock-d.silverCost*qty end; if d.goldCost then GlassKilnSealMaker.goldStock=GlassKilnSealMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GlassKilnSealMaker.jewelStock=GlassKilnSealMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GlassKilnSealMaker.pearlStock=GlassKilnSealMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GlassKilnSealMaker.maker then t=math.max(1,t-math.floor(GlassKilnSealMaker.maker.skill/13)) end; table.insert(GlassKilnSealMaker.activeMaking,{id="glasskilnseal_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GlassKilnSealMaker.completeMaking(m) local q=1.0+(GlassKilnSealMaker.getQualityBonus()/100); if GlassKilnSealMaker.maker then q=q+(GlassKilnSealMaker.maker.skill/140) end; q=math.min(2.5,q); GlassKilnSealMaker.productStock[m.productType]=(GlassKilnSealMaker.productStock[m.productType] or 0)+m.quantity; GlassKilnSealMaker.totalProducts=GlassKilnSealMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GlassKilnSealMaker.maker then GlassKilnSealMaker.maker.itemsMade=GlassKilnSealMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GlassKilnSealMaker.maker.skill=math.min(100,GlassKilnSealMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Tesnilo izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"glasskilnseal.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GlassKilnSealMaker.update(dt) if not _G.state then return end; GlassKilnSealMaker.dayTimer=GlassKilnSealMaker.dayTimer+dt; if GlassKilnSealMaker.dayTimer>=30 then GlassKilnSealMaker.dayTimer=0; for i=#GlassKilnSealMaker.activeMaking,1,-1 do local m=GlassKilnSealMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GlassKilnSealMaker.completeMaking(m); table.remove(GlassKilnSealMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GlassKilnSealMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GlassKilnSealMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GlassKilnSealMaker.getStats() return {ironStock=GlassKilnSealMaker.ironStock,bronzeStock=GlassKilnSealMaker.bronzeStock,woodStock=GlassKilnSealMaker.woodStock,leatherStock=GlassKilnSealMaker.leatherStock,silverStock=GlassKilnSealMaker.silverStock,goldStock=GlassKilnSealMaker.goldStock,jewelStock=GlassKilnSealMaker.jewelStock,pearlStock=GlassKilnSealMaker.pearlStock,productStock=GlassKilnSealMaker.productStock,numBuildings=#GlassKilnSealMaker.buildings,hasMaker=GlassKilnSealMaker.maker~=nil,makerName=GlassKilnSealMaker.maker and GlassKilnSealMaker.maker.name or "—",makerSkill=GlassKilnSealMaker.maker and GlassKilnSealMaker.maker.skill or 0,activeMaking=#GlassKilnSealMaker.activeMaking,totalProducts=GlassKilnSealMaker.totalProducts} end
return GlassKilnSealMaker
